#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "3mm.hpp"

using num_t = DATA_TYPE;

namespace {

// Base 1D vectors describing dimensions
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto l_vec = noarr::vector<'l'>();
constexpr auto m_vec = noarr::vector<'m'>();

struct tuning {
	// Layout choices are tuned for the three GEMMs:
	//   E = A * B,  F = C * D,  G = E * F
	//
	// We deliberately mix row- and column-major layouts so that
	// in each product the reduction dimension is unit-stride in
	// both operands. This improves cache locality and SIMD use.

	// A: i x k
	// scalar ^ (k_vec ^ i_vec)  -> dims (i, k) with k innermost
	// Row-major in k: A[i, k] contiguous in k (good for E-phase over k).
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);

	// B: k x j
	// scalar ^ (k_vec ^ j_vec) -> dims (j, k) with k innermost
	// Column-major w.r.t. (k, j): B[k, j] contiguous in k (also good for E-phase).
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ j_vec);

	// C: j x m
	// scalar ^ (m_vec ^ j_vec) -> dims (j, m) with m innermost
	// Row-major in m: C[j, m] contiguous in m (good for F-phase over m).
	DEFINE_PROTO_STRUCT(c_layout, m_vec ^ j_vec);

	// D: m x l
	// scalar ^ (m_vec ^ l_vec) -> dims (l, m) with m innermost
	// Column-major w.r.t. (m, l): D[m, l] contiguous in m (also good for F-phase).
	DEFINE_PROTO_STRUCT(d_layout, m_vec ^ l_vec);

	// E: i x j
	// scalar ^ (j_vec ^ i_vec) -> dims (i, j) with j innermost
	// Row-major in j: E[i, j] contiguous in j (good for G-phase over j).
	DEFINE_PROTO_STRUCT(e_layout, j_vec ^ i_vec);

	// F: j x l
	// scalar ^ (j_vec ^ l_vec) -> dims (l, j) with j innermost
	// Column-major w.r.t. (j, l): F[j, l] contiguous in j (also good for G-phase).
	DEFINE_PROTO_STRUCT(f_layout, j_vec ^ l_vec);

	// G: i x l
	// scalar ^ (l_vec ^ i_vec) -> dims (i, l) with l innermost
	// Row-major in l: G[i, l] contiguous in l (final result, convenient for output).
	DEFINE_PROTO_STRUCT(g_layout, l_vec ^ i_vec);
} tuning;

// Array initialization
// A: i x k
// B: k x j
// C: j x m
// D: m x l
void init_array(auto A, auto B, auto C, auto D) {
	using namespace noarr;

	const auto ni = A | get_length<'i'>();
	const auto nk = A | get_length<'k'>();
	const auto nj = B | get_length<'j'>();
	const auto nm = C | get_length<'m'>();
	const auto nl = D | get_length<'l'>();

	// Precompute reciprocals to avoid a division in every element.
	const num_t inv_5_ni = num_t(1) / (num_t(5) * num_t(ni));
	const num_t inv_5_nj = num_t(1) / (num_t(5) * num_t(nj));
	const num_t inv_5_nk = num_t(1) / (num_t(5) * num_t(nk));
	const num_t inv_5_nl = num_t(1) / (num_t(5) * num_t(nl));

	// A[i][k] = ((i * k + 1) % ni) / (5 * ni)
	traverser(A).for_each([&](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = num_t((i * k + 1) % ni) * inv_5_ni;
	});

	// B[k][j] = ((k * (j + 1) + 2) % nj) / (5 * nj)
	traverser(B).for_each([&](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = num_t((k * (j + 1) + 2) % nj) * inv_5_nj;
	});

	// C[j][m] = (j * (m + 3) % nl) / (5 * nl)
	traverser(C).for_each([&](auto state) {
		auto [j, m] = get_indices<'j', 'm'>(state);
		C[state] = num_t((j * (m + 3) % nl)) * inv_5_nl;
	});

	// D[m][l] = ((m * (l + 2) + 2) % nk) / (5 * nk)
	traverser(D).for_each([&](auto state) {
		auto [m, l] = get_indices<'m', 'l'>(state);
		D[state] = num_t((m * (l + 2) + 2) % nk) * inv_5_nk;
	});
}

// computation kernel
// E: i x j  = A (i x k) * B (k x j)
// F: j x l  = C (j x m) * D (m x l)
// G: i x l  = E (i x j) * F (j x l)
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	using namespace noarr;

	// Simple, cache-friendly blocking on the outer (non-reduction) dimensions.
	// Reduction dimensions (k, m, j) are left continuous and innermost,
	// benefitting from the layouts chosen in `tuning` above.

	const std::size_t tile_i = 32;
	const std::size_t tile_j = 32;
	const std::size_t tile_l = 32;

	#pragma scop
	// ------------------------------------------------------------------
	// Stage 1: E := A * B
	//   E[i, j] = sum_k A[i, k] * B[k, j]
	//   - A[i, k] and B[k, j] are both contiguous in k (by layout).
	//   - We keep a scalar accumulator in a register to avoid RMW on E.
	//   - We also block i and j to improve cache locality.
	// ------------------------------------------------------------------
	traverser(E, A, B)
		.order(
			// Split i into tiles I (block index) and i (intra-tile), guarded by 'r'
			noarr::into_blocks_dynamic<'i', 'I', 'i', 'r'>(tile_i)
			^
			// Split j into tiles J (block index) and j (intra-tile), guarded by 's'
			noarr::into_blocks_dynamic<'j', 'J', 'j', 's'>(tile_j)
		)
		.template for_dims<'I', 'J'>([&](auto trav_IJ) {
			// trav_IJ has I and J fixed; remaining dimensions include:
			//   i, r, j, s, k
			trav_IJ.template for_dims<'i', 'r', 'j', 's'>([&](auto trav_ij) {
				// Each trav_ij corresponds to one valid (i, j) inside a tile.
				num_t acc = num_t(0);

				// Reduction over k. Thanks to the chosen layouts for A and B,
				// both A[i, k] and B[k, j] are accessed with unit stride in k.
				trav_ij.template for_dims<'k'>([&](auto trav_ijk) {
					acc += A[trav_ijk] * B[trav_ijk];
				});

				// Write the accumulated result once.
				E[trav_ij] = acc;
			});
		});

	// ------------------------------------------------------------------
	// Stage 2: F := C * D
	//   F[j, l] = sum_m C[j, m] * D[m, l]
	//   - C[j, m] and D[m, l] are both contiguous in m (by layout).
	//   - Again, use a scalar accumulator and tile j and l.
	// ------------------------------------------------------------------
	traverser(F, C, D)
		.order(
			noarr::into_blocks_dynamic<'j', 'J', 'j', 'r'>(tile_j)
			^
			noarr::into_blocks_dynamic<'l', 'L', 'l', 's'>(tile_l)
		)
		.template for_dims<'J', 'L'>([&](auto trav_JL) {
			// trav_JL has J and L fixed; remaining dimensions: j, r, l, s, m
			trav_JL.template for_dims<'j', 'r', 'l', 's'>([&](auto trav_jl) {
				num_t acc = num_t(0);

				// Reduction over m; C and D are both unit-stride in m.
				trav_jl.template for_dims<'m'>([&](auto trav_jlm) {
					acc += C[trav_jlm] * D[trav_jlm];
				});

				F[trav_jl] = acc;
			});
		});

	// ------------------------------------------------------------------
	// Stage 3: G := E * F
	//   G[i, l] = sum_j E[i, j] * F[j, l]
	//   - E[i, j] and F[j, l] are both contiguous in j (by layout).
	//   - Tile i and l, and use a scalar accumulator for G[i, l].
	// ------------------------------------------------------------------
	traverser(G, E, F)
		.order(
			noarr::into_blocks_dynamic<'i', 'I', 'i', 'r'>(tile_i)
			^
			noarr::into_blocks_dynamic<'l', 'L', 'l', 's'>(tile_l)
		)
		.template for_dims<'I', 'L'>([&](auto trav_IL) {
			// trav_IL has I and L fixed; remaining dimensions: i, r, l, s, j
			trav_IL.template for_dims<'i', 'r', 'l', 's'>([&](auto trav_il) {
				num_t acc = num_t(0);

				// Reduction over j; E and F are both unit-stride in j.
				trav_il.template for_dims<'j'>([&](auto trav_ilj) {
					acc += E[trav_ilj] * F[trav_ilj];
				});

				G[trav_il] = acc;
			});
		});
	#pragma endscop
}

} // namespace

