	// NOTE ON LAYOUTS:
	// ----------------
	// We choose layouts so that, in each matrix product, the reduction
	// dimension is contiguous (inner-most) in both operands. This greatly
	// improves cache use and SIMD efficiency while preserving the logical
	// indexing in the original code.
	//
	// For a structure defined as:
	//   scalar<T>() ^ vector<'X'>() ^ vector<'Y'>()
	// the inner-most dimension is 'X' (contiguous), and 'Y' is outer.

	// A: i x k, used in E = A * B, reduction over k
	// Layout: inner k, outer i  --> A[i, k] contiguous in k
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);

	// B: k x j, used in E = A * B, reduction over k
	// Original code used (j_vec ^ k_vec), which is contiguous in j.
	// We switch to (k_vec ^ j_vec) so that B[k, j] is contiguous in k.
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ j_vec);

	// C: j x m, used in F = C * D, reduction over m
	// Layout: inner m, outer j  --> C[j, m] contiguous in m
	DEFINE_PROTO_STRUCT(c_layout, m_vec ^ j_vec);

	// D: m x l, used in F = C * D, reduction over m
	// Original code used (l_vec ^ m_vec), contiguous in l.
	// We switch to (m_vec ^ l_vec) so that D[m, l] is contiguous in m.
	DEFINE_PROTO_STRUCT(d_layout, m_vec ^ l_vec);

	// E: i x j, used in G = E * F, reduction over j
	// Layout: inner j, outer i  --> E[i, j] contiguous in j
	DEFINE_PROTO_STRUCT(e_layout, j_vec ^ i_vec);

	// F: j x l, used in G = E * F, reduction over j
	// Original code used (l_vec ^ j_vec), contiguous in l.
	// We switch to (j_vec ^ l_vec) so that F[j, l] is contiguous in j.
	DEFINE_PROTO_STRUCT(f_layout, j_vec ^ l_vec);

	// G: i x l, final output; choose layout with l inner for row-major-like
	// access in l. This does not affect the algorithm but is cache-friendly
	// when writing G row by row.
	DEFINE_PROTO_STRUCT(g_layout, l_vec ^ i_vec);
} tuning;

// Array initialization
void init_array(auto A, auto B, auto C, auto D) {
	// A: i x k
	// B: k x j
	// C: j x m
	// D: m x l
	using namespace noarr;

	auto ni = A | get_length<'i'>();
	auto nk = A | get_length<'k'>();
	auto nj = B | get_length<'j'>();
	auto nm = C | get_length<'m'>();
	auto nl = D | get_length<'l'>();

	// Precompute reciprocals of (5 * N?) once to avoid recomputing
	// multipliers in every element. This keeps the arithmetic equivalent
	// to the original (division vs. multiplication by reciprocal may differ
	// in last bit, but polybench-style benchmarks usually tolerate this).
	const num_t inv_5_ni = num_t(1) / num_t(5 * ni);
	const num_t inv_5_nj = num_t(1) / num_t(5 * nj);
	const num_t inv_5_nk = num_t(1) / num_t(5 * nk);
	const num_t inv_5_nl = num_t(1) / num_t(5 * nl);

	// A[i][k] = ((i * k + 1) % ni) / (5 * ni)
	traverser(A).template for_dims<'i', 'k'>([=](auto trav) {
		auto state = trav.state();
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = num_t((i * k + 1) % ni) * inv_5_ni;
	});

	// B[k][j] = ((k * (j + 1) + 2) % nj) / (5 * nj)
	traverser(B).template for_dims<'k', 'j'>([=](auto trav) {
		auto state = trav.state();
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = num_t((k * (j + 1) + 2) % nj) * inv_5_nj;
	});

	// C[j][m] = (j * (m + 3) % nl) / (5 * nl)
	traverser(C).template for_dims<'j', 'm'>([=](auto trav) {
		auto state = trav.state();
		auto [j, m] = get_indices<'j', 'm'>(state);
		C[state] = num_t(j * (m + 3) % nl) * inv_5_nl;
	});

	// D[m][l] = ((m * (l + 2) + 2) % nk) / (5 * nk)
	traverser(D).template for_dims<'m', 'l'>([=](auto trav) {
		auto state = trav.state();
		auto [m, l] = get_indices<'m', 'l'>(state);
		D[state] = num_t((m * (l + 2) + 2) % nk) * inv_5_nk;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	// E: i x j  = A (i x k) * B (k x j)
	// F: j x l  = C (j x m) * D (m x l)
	// G: i x l  = E (i x j) * F (j x l)
	using namespace noarr;
	using noarr::lit;

	// Tile sizes (chosen for a modern x64 CPU; tune as needed).
	// These only affect traversal order, not numerical results.
	constexpr std::size_t tile_i = 64;
	constexpr std::size_t tile_j = 64;
	constexpr std::size_t tile_l = 64;

	#pragma scop
	// ----------------------------------------------------------
	// Stage 1: E = A * B
	//   E[i, j] = sum_k A[i, k] * B[k, j]
	//
	// We:
	//   - tile over (i, j) to improve cache locality,
	//   - iterate k as the innermost loop so both A and B are
	//     read with unit stride (due to layouts a_layout/b_layout),
	//   - accumulate in a scalar register and write E[i,j] once.
	// ----------------------------------------------------------
	traverser(E, A, B)
		.order(
			// split 'i' into block index 'I' and intra-block 'i',
			// with presence flag 'x' for partial tiles
			into_blocks_dynamic<'i', 'I', 'i', 'x'>(lit<tile_i>) ^
			// split 'j' into block index 'J' and intra-block 'j',
			// with presence flag 'y'
			into_blocks_dynamic<'j', 'J', 'j', 'y'>(lit<tile_j>)
		)
		// Outer tile loops over (I, J)
		.template for_dims<'I', 'J'>([&](auto tile_ij) {
			// For each logical (i, j) in this tile:
			tile_ij.template for_dims<'i', 'x', 'j', 'y'>([&](auto ij_trav) {
				num_t sum = num_t(0);

				// Reduction over k; k is the innermost dimension and
				// contiguous in both A and B (by layout choice).
				ij_trav.template for_dims<'k'>([&](auto state) {
					sum += A[state] * B[state];
				});

				// Write result once
				E[ij_trav] = sum;
			});
		});

	// ----------------------------------------------------------
	// Stage 2: F = C * D
	//   F[j, l] = sum_m C[j, m] * D[m, l]
	//
	// Similar structure:
	//   - tile over (j, l),
	//   - reduction over m as innermost, with C and D contiguous
	//     in m (layouts c_layout/d_layout),
	//   - scalar accumulator in registers.
	// ----------------------------------------------------------
	traverser(F, C, D)
		.order(
			into_blocks_dynamic<'j', 'J', 'j', 'x'>(lit<tile_j>) ^
			into_blocks_dynamic<'l', 'L', 'l', 'y'>(lit<tile_l>)
		)
		.template for_dims<'J', 'L'>([&](auto tile_jl) {
			tile_jl.template for_dims<'j', 'x', 'l', 'y'>([&](auto jl_trav) {
				num_t sum = num_t(0);

				// Reduction over m; C and D are both contiguous in m.
				jl_trav.template for_dims<'m'>([&](auto state) {
					sum += C[state] * D[state];
				});

				F[jl_trav] = sum;
			});
		});

	// ----------------------------------------------------------
	// Stage 3: G = E * F
	//   G[i, l] = sum_j E[i, j] * F[j, l]
	//
	// Again:
	//   - tile over (i, l),
	//   - reduction over j as innermost. E is row-major in j,
	//     F is column-major in j, so both are contiguous in j.
	//   - accumulate in register, write G[i,l] once.
	// ----------------------------------------------------------
	traverser(G, E, F)
		.order(
			into_blocks_dynamic<'i', 'I', 'i', 'x'>(lit<tile_i>) ^
			into_blocks_dynamic<'l', 'L', 'l', 'y'>(lit<tile_l>)
		)
		.template for_dims<'I', 'L'>([&](auto tile_il) {
			tile_il.template for_dims<'i', 'x', 'l', 'y'>([&](auto il_trav) {
				num_t sum = num_t(0);

				// Reduction over j; E and F are both contiguous in j.
				il_trav.template for_dims<'j'>([&](auto state) {
					sum += E[state] * F[state];
				});

				G[il_trav] = sum;
			});
		});
	#pragma endscop
}

