	// A: i x k, row-major in k (k is the fast-varying / contiguous dim)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);

	// B: k x j, row-major in j (j is contiguous)
	//   This pairs well with the loop order i -> k -> j in the first GEMM:
	//   for a fixed (i, k), we sweep j as the innermost loop so both B[k, j]
	//   and E[i, j] are accessed with unit stride.
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ k_vec);

	// C: j x m, row-major in m (m is contiguous)
	DEFINE_PROTO_STRUCT(c_layout, m_vec ^ j_vec);

	// D: m x l, row-major in l (l is contiguous)
	//   This pairs with loop order j -> m -> l in the second GEMM.
	DEFINE_PROTO_STRUCT(d_layout, l_vec ^ m_vec);

	// E: i x j, row-major in j (j is contiguous)
	DEFINE_PROTO_STRUCT(e_layout, j_vec ^ i_vec);

	// F: j x l, row-major in l (l is contiguous)
	//   This pairs with loop order i -> j -> l in the third GEMM.
	DEFINE_PROTO_STRUCT(f_layout, l_vec ^ j_vec);

	// G: i x l, row-major in l (l is contiguous, final result)
	DEFINE_PROTO_STRUCT(g_layout, l_vec ^ i_vec);
} tuning;

// Array initialization
void init_array(auto A, auto B, auto C, auto D) {
	// A: i x k
	// B: k x j
	// C: j x m
	// D: m x l
	using namespace noarr;

	auto ni = A | get_length<'i'>();
	auto nk = A | get_length<'k'>();
	auto nj = B | get_length<'j'>();
	auto nm = C | get_length<'m'>();
	auto nl = D | get_length<'l'>();

	// A[i][k] = ((i * k + 1) % ni) / (5 * ni)
	traverser(A).template for_dims<'i', 'k'>([=](auto trav) {
		auto state = trav.state();
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % ni) / (5 * ni);
	});

	// B[k][j] = ((k * (j + 1) + 2) % nj) / (5 * nj)
	traverser(B).template for_dims<'k', 'j'>([=](auto trav) {
		auto state = trav.state();
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = (num_t)((k * (j + 1) + 2) % nj) / (5 * nj);
	});

