// computation kernel
//
// Optimized for data locality:
//
// - Stage 1: E = A * B
//     Loop order: i -> k -> j
//       A: row-major in k  (A[i, k] contiguous in k)
//       B: row-major in j  (B[k, j] contiguous in j)
//       E: row-major in j  (E[i, j] contiguous in j)
//     For fixed (i, k), A[i, k] is a scalar (kept in a register) and
//     we sweep j innermost, streaming across B[k, j] and E[i, j].
//
// - Stage 2: F = C * D
//     Loop order: j -> m -> l
//       C: row-major in m  (C[j, m] contiguous in m)
//       D: row-major in l  (D[m, l] contiguous in l)
//       F: row-major in l  (F[j, l] contiguous in l)
//     For fixed (j, m), C[j, m] is a scalar and we sweep l innermost,
//     streaming across D[m, l] and F[j, l].
//
// - Stage 3: G = E * F
//     Loop order: i -> j -> l
//       E: row-major in j  (E[i, j] contiguous in j)
//       F: row-major in l  (F[j, l] contiguous in l)
//       G: row-major in l  (G[i, l] contiguous in l)
//     For fixed (i, j), E[i, j] is a scalar and we sweep l innermost,
//     streaming across F[j, l] and G[i, l].
//
// All loop nests are expressed via Noarr traversers and for_dims.
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	// E: i x j  = A (i x k) * B (k x j)
	// F: j x l  = C (j x m) * D (m x l)
	// G: i x l  = E (i x j) * F (j x l)
	using namespace noarr;

	#pragma scop
	// -----------------------------------------------------------------
	// Stage 1: E := A * B
	//   E[i, j] = sum_k A[i, k] * B[k, j]
	//   Loop order: i -> k -> j, to stream along j (fast dimension)
	// -----------------------------------------------------------------

	// Initialize E to zero
	traverser(E).for_each([&](auto state) {
		E[state] = (num_t)0.0;
	});

	// GEMM-like accumulation with improved access pattern
	traverser(E, A, B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, 'k' and 'j' free

		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed, 'j' free
			// Load A[i, k] once and reuse it across all j in this row/column pair.
			num_t aik = A[trav_ik];

			trav_ik.template for_dims<'j'>([&](auto trav_ijk) {
				// innermost loop over j hits B[k, j] and E[i, j] contiguously in memory
				E[trav_ijk] += aik * B[trav_ijk];
			});
		});
	});

	// -----------------------------------------------------------------
	// Stage 2: F := C * D
	//   F[j, l] = sum_m C[j, m] * D[m, l]
	//   Loop order: j -> m -> l, to stream along l (fast dimension)
	// -----------------------------------------------------------------

	// Initialize F to zero
	traverser(F).for_each([&](auto state) {
		F[state] = (num_t)0.0;
	});

	traverser(F, C, D).template for_dims<'j'>([&](auto trav_j) {
		// trav_j has 'j' fixed, 'm' and 'l' free

		trav_j.template for_dims<'m'>([&](auto trav_jm) {
			// trav_jm has 'j' and 'm' fixed, 'l' free
			num_t cjm = C[trav_jm];

			trav_jm.template for_dims<'l'>([&](auto trav_jml) {
				// innermost loop over l hits D[m, l] and F[j, l] contiguously
				F[trav_jml] += cjm * D[trav_jml];
			});
		});
	});

	// -----------------------------------------------------------------
	// Stage 3: G := E * F
	//   G[i, l] = sum_j E[i, j] * F[j, l]
	//   Loop order: i -> j -> l, to stream along l (fast dimension)
	// -----------------------------------------------------------------

	// Initialize G to zero
	traverser(G).for_each([&](auto state) {
		G[state] = (num_t)0.0;
	});

	traverser(G, E, F).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, 'j' and 'l' free

		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			// trav_ij has 'i' and 'j' fixed, 'l' free
			num_t eij = E[trav_ij];

			trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
				// innermost loop over l streams G[i, l] and F[j, l]
				G[trav_ijl] += eij * F[trav_ijl];
			});
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;
	std::size_t nm = NM;

	// set lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl) ^
		noarr::set_length<'m'>(nm);

	// allocate data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto D = noarr::bag(noarr::scalar<num_t>() ^ tuning.d_layout ^ set_lengths);
	auto E = noarr::bag(noarr::scalar<num_t>() ^ tuning.e_layout ^ set_lengths);
	auto F = noarr::bag(noarr::scalar<num_t>() ^ tuning.f_layout ^ set_lengths);
	auto G = noarr::bag(noarr::scalar<num_t>() ^ tuning.g_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_3mm(E.get_ref(), A.get_ref(), B.get_ref(),
	           F.get_ref(), C.get_ref(), D.get_ref(), G.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, G.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
