		num_t acc = num_t(0);

		trav_jl.template for_dims<'m'>([&](auto trav_jlm) {
			acc += C[trav_jlm] * D[trav_jlm];
		});

		F[trav_jl] = acc;
	});

	// -----------------------------------------------------------------
	// Stage 3: G := E * F
	//   G[i, l] = sum_j E[i, j] * F[j, l]
	//   Traversal order: i, l, then reduction over j.
	//   Layouts:
	//     - E: j (inner), i (outer)    => contiguous in j
	//     - F: j (inner), l (outer)    => contiguous in j
	//   so the innermost j-loop streams both operands contiguously.
	// -----------------------------------------------------------------
	traverser(G, E, F).template for_dims<'i', 'l'>([=](auto trav_il) {
		num_t acc = num_t(0);

		trav_il.template for_dims<'j'>([&](auto trav_ilj) {
			acc += E[trav_ilj] * F[trav_ilj];
